//  FIREBASE SDK LOADER (lazy, CDN, no npm install needed) 
let _firebaseAuthPromise = null;
function loadFirebaseAuth() {
  if (_firebaseAuthPromise) return _firebaseAuthPromise;
  _firebaseAuthPromise = (async () => {
    const appMod = await import("https://www.gstatic.com/firebasejs/10.13.0/firebase-app.js");
    const authMod = await import("https://www.gstatic.com/firebasejs/10.13.0/firebase-auth.js");
    const app = appMod.getApps().length ? appMod.getApp() : appMod.initializeApp(FIREBASE_CONFIG);
    const auth = authMod.getAuth(app);
    return { app, auth, authMod };
  })();
  return _firebaseAuthPromise;
}

//  FIRESTORE LOADER (lazy, CDN, web) — used to persist per-account stats 
let _firestorePromise = null;
function loadFirestore() {
  if (_firestorePromise) return _firestorePromise;
  _firestorePromise = (async () => {
    const appMod = await import("https://www.gstatic.com/firebasejs/10.13.0/firebase-app.js");
    const fsMod = await import("https://www.gstatic.com/firebasejs/10.13.0/firebase-firestore.js");
    const app = appMod.getApps().length ? appMod.getApp() : appMod.initializeApp(FIREBASE_CONFIG);
    // Long-polling auto-detect makes Firestore reliable inside the Android WebView
    // (the default WebChannel transport can stall there). Falls back if already init'd.
    let db;
    try {
      db = fsMod.initializeFirestore(app, { experimentalAutoDetectLongPolling: true });
    } catch {
      db = fsMod.getFirestore(app);
    }
    return { db, fsMod };
  })();
  return _firestorePromise;
}

//  NATIVE FIRESTORE (Capacitor plugin, Android) 
// Capacitor Firestore accessed via window.Capacitor.Plugins at runtime (no import needed)
function loadCapacitorFirestore() {
  const FirebaseFirestore = window?.Capacitor?.Plugins?.FirebaseFirestore;
  if (!FirebaseFirestore) throw new Error("CAPACITOR_FIRESTORE_MISSING");
  return Promise.resolve(FirebaseFirestore);
}

//  STATS PERSISTENCE 
// Real accounts (email/Google): saved to Firestore under users/{uid}, so
// progress survives logout and re-installs. Guests: saved to localStorage on
// this device only, so it survives app restarts but never leaves the device.
const DEFAULT_STATS = { quizCompleted: 0, lessonsOpened: 0, streak: 0, lastDate: null, bestScore: 0, totalScore: 0, bestStreak: 0, monthKey: null, monthActiveDays: [], monthlyBadges: [], firstMonth: null, dailyMinutes: {}, tenureActiveMonths: [], lastSeenTenureCount: 0 };
const GUEST_STATS_KEY = "school-maroc-guest-stats";

function loadGuestStats() {
  try {
    const raw = window.localStorage.getItem(GUEST_STATS_KEY);
    return raw ? { ...DEFAULT_STATS, ...JSON.parse(raw) } : { ...DEFAULT_STATS };
  } catch {
    return { ...DEFAULT_STATS };
  }
}

function saveGuestStats(stats) {
  try { window.localStorage.setItem(GUEST_STATS_KEY, JSON.stringify(stats)); } catch {}
}

async function loadAccountStats(uid) {
  const { db, fsMod } = await loadFirestore();
  const ref = fsMod.doc(db, "users", uid);
  const snap = await fsMod.getDoc(ref);
  return snap.exists() ? { ...DEFAULT_STATS, ...snap.data() } : { ...DEFAULT_STATS };
}

async function saveAccountStats(uid, stats) {
  const { db, fsMod } = await loadFirestore();
  const ref = fsMod.doc(db, "users", uid);
  await fsMod.setDoc(ref, stats, { merge: true });
}

//  EXAM COUNTDOWN CONFIG 
// Official exam dates, set once by the admin (admin4.html) for the four
// grades that sit an official national exam. Stored in Firestore at
// config/examDates as {"6ap": "YYYY-MM-DD", "3ac": "...", "1bac": "...", "2bac": "..."}
// so every user sees the same date, cached to localStorage for instant /
// offline display.
const EXAM_DATE_GRADE_IDS = ["6ap", "3ac", "1bac", "2bac"];
const EXAM_DATES_CACHE_KEY = "school-maroc-exam-dates";

function loadCachedExamDates() {
  try {
    const raw = window.localStorage.getItem(EXAM_DATES_CACHE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function cacheExamDates(dates) {
  try { window.localStorage.setItem(EXAM_DATES_CACHE_KEY, JSON.stringify(dates)); } catch {}
}

async function fetchExamDates() {
  const { db, fsMod } = await loadFirestore();
  const ref = fsMod.doc(db, "config", "examDates");
  const snap = await fsMod.getDoc(ref);
  const dates = snap.exists() ? snap.data() : {};
  cacheExamDates(dates);
  return dates;
}

// Turns an exam date ("YYYY-MM-DD") into a calendar-accurate { months, days,
// expired } breakdown of time remaining from today (not a flat /30 division,
// so "1 mois" always lands on the same day next month).
function examCountdownFrom(dateStr) {
  if (!dateStr) return null;
  const target = new Date(dateStr + "T00:00:00");
  if (isNaN(target.getTime())) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  if (target <= today) return { months: 0, days: 0, expired: true };

  let months = (target.getFullYear() - today.getFullYear()) * 12 + (target.getMonth() - today.getMonth());
  let cursor = new Date(today.getFullYear(), today.getMonth() + months, today.getDate());
  if (cursor > target) {
    months -= 1;
    cursor = new Date(today.getFullYear(), today.getMonth() + months, today.getDate());
  }
  const days = Math.round((target - cursor) / 86400000);
  return { months, days, expired: false };
}


function mapFirebaseError(code) {
  switch (code) {
    case "auth/invalid-email": return "Adresse email invalide.";
    case "auth/user-disabled": return "Ce compte a été désactivé.";
    case "auth/user-not-found": return "Aucun compte avec cet email.";
    case "auth/wrong-password": return "Mot de passe incorrect.";
    case "auth/invalid-credential": return "Email ou mot de passe incorrect.";
    case "auth/email-already-in-use": return "Cet email est déjà utilisé.";
    case "auth/weak-password": return "Mot de passe trop faible (6 caractères min).";
    case "auth/too-many-requests": return "Trop de tentatives. Réessaie plus tard.";
    case "auth/popup-closed-by-user": return "Connexion Google annulée.";
    case "auth/network-request-failed": return "Problème de connexion réseau.";
    case "auth/api-key-not-valid": case "auth/invalid-api-key":
      return "Configuration Firebase manquante (voir FIREBASE_CONFIG dans le code).";
    case "auth/unauthorized-domain":
      return "Domaine non autorisé pour Firebase Auth (à ajouter dans Authentication > Settings > Authorized domains).";
    default:
      return code ? `Erreur : ${code}` : "Une erreur est survenue. Réessaie.";
  }
}

function mapGoogleSignInError(e) {
  const msg = e?.message || "";
  const code = e?.code;
  const raw = e?._raw || "";
  // Show full error in dev so we can diagnose
  const detail = raw || msg || String(code) || "?";
  // Google Sign-In native error 10 = DEVELOPER_ERROR
  // Causes: wrong Web Client ID, SHA-1 mismatch, or google-services.json outdated
  if (msg.includes("10") || code === 10 || msg.includes("DEVELOPER_ERROR")) {
    return `Erreur Google Sign-In (code 10 - DEVELOPER_ERROR). Vérifie : 1) Web Client ID correct dans le code 2) SHA-1 enregistré dans Firebase 3) google-services.json à jour. Détail: ${detail}`;
  }
  if (msg.includes("12501") || msg.includes("SIGN_IN_CANCELLED")) {
    return "Connexion Google annulée.";
  }
  if (msg.includes("7") || msg.includes("NETWORK_ERROR")) {
    return "Problème de connexion réseau.";
  }
  if (msg === "PLUGIN_MISSING") {
    return "Plugin Google non disponible sur cet appareil.";
  }
  if (msg === "No idToken returned from Google Sign-In") {
    return "Google Sign-In n'a pas retourné de token. Réessaie.";
  }
  return mapFirebaseError(code) || `Erreur Google: ${detail}` || "Erreur de connexion Google.";
}

function firebaseUserToAppUser(fbUser, fallbackName) {
  return {
    uid: fbUser.uid,
    name: fbUser.displayName || fallbackName || (fbUser.email ? fbUser.email.split("@")[0] : "Utilisateur"),
    email: fbUser.email || "",
    avatar: fbUser.photoURL || null,
    provider: fbUser.providerData?.[0]?.providerId === "google.com" ? "google" : "email",
  };
}

//  PLATFORM DETECTION 
// True only when running inside the actual Capacitor Android/iOS app (the built
// APK), false in a normal browser tab or an embedded web preview.
//  PLATFORM DETECTION 
function isNativeApp() {
  return !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
}
function isWebView() {
  if (window.Capacitor) return true;
  const ua = navigator.userAgent || "";
  return /wv|WebView|Android.*Version\/\d|iPhone.*AppleWebKit(?!.*Safari)/i.test(ua);
}

//  NATIVE GOOGLE SIGN-IN via @capacitor-community/google-auth 
// This is simpler to install than @capacitor-firebase/authentication:
//
//   npm install @capacitor-community/google-auth
//   npx cap sync
//
// Then in android/app/src/main/AndroidManifest.xml inside <application>:
//   <meta-data android:name="com.google.android.gms.version"
//              android:value="@integer/google_play_services_version" />
//
// And add your Web Client ID (from Firebase Console → Authentication →
// Sign-in method → Google → Web client ID) to capacitor.config.ts:
//   plugins: { GoogleAuth: { clientId: "XXXXXXXX.apps.googleusercontent.com",
//                            scopes: ["profile","email"], serverClientId: "XXXXXXXX.apps.googleusercontent.com" } }

async function signInWithGoogleNative() {
  // Access Capacitor plugins via window.Capacitor.Plugins at runtime.
  // No import() needed — plugins register on the global when the APK loads them.
  // This avoids Vite/Rolldown trying to bundle native Capacitor packages.
  const plugins = window?.Capacitor?.Plugins;

  // Try GoogleAuth plugin first (@capacitor-community/google-auth)
  // IMPORTANT: clientId must be the WEB client ID from Firebase Console
  // (Authentication → Sign-in method → Google → Web client ID)
  // NOT the Android client ID. The web client ID ends in .apps.googleusercontent.com
  // and starts with your project number followed by a long hash.
  const WEB_CLIENT_ID = "1075264997229-9rto96jqi615lutr8h0jipct2bagr4vj.apps.googleusercontent.com";
  const GoogleAuth = plugins?.GoogleAuth;
  if (GoogleAuth) {
    try {
      await GoogleAuth.initialize({
        clientId: WEB_CLIENT_ID,
        serverClientId: WEB_CLIENT_ID,
        scopes: ["profile", "email"],
        grantOfflineAccess: true,
      });
      const googleUser = await GoogleAuth.signIn();
      const idToken = googleUser?.authentication?.idToken;
      if (!idToken) throw new Error("No idToken returned from Google Sign-In");
      const { auth, authMod } = await loadFirebaseAuth();
      const credential = authMod.GoogleAuthProvider.credential(idToken);
      const result = await authMod.signInWithCredential(auth, credential);
      const u = result.user;
      return {
        uid: u.uid,
        name: u.displayName || (u.email ? u.email.split("@")[0] : "Utilisateur"),
        email: u.email || "",
        avatar: u.photoURL || null,
        provider: "google",
      };
    } catch (e1) {
      // Attach raw error info for debugging
      e1._raw = JSON.stringify({ message: e1.message, code: e1.code });
      throw e1;
    }
  }

  // Fallback: try FirebaseAuthentication plugin (@capacitor-firebase/authentication)
  const FirebaseAuthentication = plugins?.FirebaseAuthentication;
  if (FirebaseAuthentication) {
    const result = await FirebaseAuthentication.signInWithGoogle();
    const u = result.user;
    return {
      uid: u.uid,
      name: u.displayName || (u.email ? u.email.split("@")[0] : "Utilisateur"),
      email: u.email || "",
      avatar: u.photoUrl || null,
      provider: "google",
    };
  }

  // Neither plugin available at runtime
  throw new Error("PLUGIN_MISSING");
}

