//  Ripple click effect hook 
function useRipple() {
  const [ripples, setRipples] = useState([]);
  const addRipple = useCallback((e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const id = Date.now();
    setRipples(r => [...r, { id, x, y }]);
    setTimeout(() => setRipples(r => r.filter(rp => rp.id !== id)), 600);
  }, []);
  const RippleLayer = () => (
    <>
      {ripples.map(rp => (
        <span key={rp.id} className="ripple-wave" style={{ left: rp.x, top: rp.y }} />
      ))}
    </>
  );
  return { addRipple, RippleLayer };
}

//  Scroll-fade hook: returns 0→1 as the page scrolls past `range` px 
// `resetKey` should change whenever the visible "page" changes (e.g. the
// page/matiere navigation state). Without this, the fade value — and the
// scroll position itself — carries over from whatever page you were on
// before, so a fresh/short page (like an error or loading state) can land
// already fully faded, making the header-to-body corner look flat even
// though the border-radius is still technically applied.
function useScrollFade(range = 100, resetKey) {
  const [fade, setFade] = useState(0);
  useEffect(() => {
    const getY = () =>
      window.scrollY ||
      document.documentElement.scrollTop ||
      document.body.scrollTop || 0;
    const onScroll = () => {
      const y = getY();
      setFade(Math.min(1, Math.max(0, y / range)));
    };
    // Snap scroll back to top and recompute fade whenever we navigate to a
    // new page, instead of inheriting the previous page's scroll position.
    try { window.scrollTo(0, 0); } catch {}
    setFade(0);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    document.addEventListener("scroll", onScroll, { passive: true, capture: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      document.removeEventListener("scroll", onScroll, { capture: true });
    };
  }, [range, resetKey]);
  return fade;
}

//  Elastic overscroll hook: rubber-band stretch on the body container 
// Returns a ref to attach to the scrollable body element and a translateY (px)
// to apply via transform, springing back to 0 when the gesture ends.
function useElasticOverscroll() {
  const ref = useRef(null);
  const [offset, setOffset] = useState(0);
  const stateRef = useRef({ touchY: 0, dragging: false });

  useEffect(() => {
    const MAX = 70;        // max pixels of stretch
    const RESIST = 0.4;    // resistance factor (rubber-band feel)

    const atTop = () => (window.scrollY || document.documentElement.scrollTop || 0) <= 0;
    const atBottom = () => {
      const scrollY = window.scrollY || document.documentElement.scrollTop || 0;
      const viewport = window.innerHeight;
      const full = document.documentElement.scrollHeight;
      return scrollY + viewport >= full - 1;
    };

    const onTouchStart = (e) => {
      stateRef.current.touchY = e.touches[0].clientY;
      stateRef.current.dragging = true;
    };
    const onTouchMove = (e) => {
      if (!stateRef.current.dragging) return;
      const y = e.touches[0].clientY;
      const delta = y - stateRef.current.touchY;
      if (delta > 0 && atTop()) {
        setOffset(Math.min(MAX, delta * RESIST));
      } else if (delta < 0 && atBottom()) {
        setOffset(Math.max(-MAX, delta * RESIST));
      } else {
        setOffset(0);
      }
    };
    const onTouchEnd = () => {
      stateRef.current.dragging = false;
      setOffset(0);
    };

    // Desktop: subtle wheel-based bounce at boundaries
    let wheelTimeout;
    const onWheel = (e) => {
      if (e.deltaY < 0 && atTop()) {
        setOffset(Math.min(MAX, -e.deltaY * RESIST * 0.3));
      } else if (e.deltaY > 0 && atBottom()) {
        setOffset(Math.max(-MAX, -e.deltaY * RESIST * 0.3));
      } else {
        return;
      }
      clearTimeout(wheelTimeout);
      wheelTimeout = setTimeout(() => setOffset(0), 150);
    };

    window.addEventListener("touchstart", onTouchStart, { passive: true });
    window.addEventListener("touchmove", onTouchMove, { passive: true });
    window.addEventListener("touchend", onTouchEnd, { passive: true });
    window.addEventListener("wheel", onWheel, { passive: true });
    return () => {
      window.removeEventListener("touchstart", onTouchStart);
      window.removeEventListener("touchmove", onTouchMove);
      window.removeEventListener("touchend", onTouchEnd);
      window.removeEventListener("wheel", onWheel);
      clearTimeout(wheelTimeout);
    };
  }, []);

  const style = {
    transform: `translateY(${offset}px)`,
    transition: offset === 0 ? "transform 0.35s cubic-bezier(0.34,1.56,0.64,1)" : "transform 0s",
  };

  return { ref, style };
}

//  THEME 
//  GLOBAL STATS helpers (state lives in App, passed via props) 
function recordStreakAndDate(s) {
  const today = new Date().toDateString();
  const yesterday = new Date(Date.now() - 86400000).toDateString();
  const streak = s.lastDate === today ? s.streak
    : s.lastDate === yesterday ? s.streak + 1 : 1;
  return { streak, lastDate: today };
}

//  MONTHLY BADGES (Duolingo-style monthly medal, resets every calendar month) 
const MONTH_NAMES_FR = ["Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre"];
const MONTH_NAMES_AR = ["يناير","فبراير","مارس","أبريل","ماي","يونيو","يوليوز","غشت","شتنبر","أكتوبر","نونبر","دجنبر"];
function monthNamesUI() { return getAppLang() === "ar" ? MONTH_NAMES_AR : MONTH_NAMES_FR; }
function monthKeyOf(date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`; }
function monthLabelOf(monthKey) {
  const [y, m] = monthKey.split("-").map(Number);
  return `${monthNamesUI()[m - 1]} ${y}`;
}
// Returns every month key from startKey up to (but excluding) endKeyExclusive,
// e.g. monthsBetween("2026-02", "2026-05") -> ["2026-02","2026-03","2026-04"]
function monthsBetween(startKey, endKeyExclusive) {
  if (!startKey) return [];
  const [sy, sm] = startKey.split("-").map(Number);
  const [ey, em] = endKeyExclusive.split("-").map(Number);
  const out = [];
  let y = sy, m = sm;
  while (y < ey || (y === ey && m < em)) {
    out.push(`${y}-${String(m).padStart(2, "0")}`);
    m++;
    if (m > 12) { m = 1; y++; }
  }
  return out;
}
// Tiers are based on the number of DISTINCT DAYS active in the calendar
// month (exactly how Duolingo's monthly badge works: it's a day-streak
// count within the month, not a raw event counter — doing 10 quizzes in
// one day still counts as 1 active day).
const MONTHLY_TIERS = [
  { id: "bronze",  label: "Bronze",  min: 5,  color: "#CD7F32" },
  { id: "argent",  label: "Argent",  min: 10, color: "#9CA3AF" },
  { id: "or",      label: "Or",      min: 18, color: "#F1C40F" },
  { id: "diamant", label: "Diamant", min: 25, color: "#5DADE2" },
];
function tierForActivity(daysActive) {
  let tier = null;
  for (const t of MONTHLY_TIERS) if (daysActive >= t.min) tier = t;
  return tier;
}
function daysInMonth(monthKey) {
  const [y, m] = monthKey.split("-").map(Number);
  return new Date(y, m, 0).getDate();
}
// Weekday (0=Mon..6=Sun) of the 1st of the month, for a Monday-first grid.
function firstWeekdayMonday(monthKey) {
  const [y, m] = monthKey.split("-").map(Number);
  const jsDay = new Date(y, m - 1, 1).getDay(); // 0=Sun..6=Sat
  return (jsDay + 6) % 7;
}
// Marks today's day-of-month as active. If the calendar month has rolled
// over since the last activity, the previous month is archived into
// monthlyBadges (tier: null if it never reached Bronze) so the full
// history — including quiet months — can be rebuilt from firstMonth onward.
function recordMonthlyActivity(s) {
  const now = new Date();
  const currentMonth = monthKeyOf(now);
  const today = now.getDate();
  const firstMonth = s.firstMonth || s.monthKey || currentMonth;
  if (s.monthKey && s.monthKey !== currentMonth) {
    const prevDays = s.monthActiveDays || [];
    const prevTier = tierForActivity(prevDays.length);
    const already = (s.monthlyBadges || []).some(b => b.month === s.monthKey);
    const monthlyBadges = already
      ? s.monthlyBadges
      : [...(s.monthlyBadges || []), { month: s.monthKey, tier: prevTier ? prevTier.id : null, activeDays: prevDays.length }];
    return { monthKey: currentMonth, monthActiveDays: [today], monthlyBadges, firstMonth };
  }
  const existingDays = s.monthKey === currentMonth ? (s.monthActiveDays || []) : [];
  const monthActiveDays = existingDays.includes(today) ? existingDays : [...existingDays, today];
  return {
    monthKey: currentMonth,
    monthActiveDays,
    monthlyBadges: s.monthlyBadges || [],
    firstMonth,
  };
}

//  TENURE BADGES (5 lifetime badges based on TOTAL months the user was active) 
// A day counts as "active" once the user has spent at least ACTIVE_DAY_MIN_MINUTES
// with lessons, exercises, or quizzes open that day. A calendar month counts as
// an "active month" once it has reached ACTIVE_MONTH_MIN_DAYS such days. Every
// active month (starting the month the user first opened the app) adds +1 to a
// lifetime counter — gaps/inactive months don't reset it. The badge earned from
// that lifetime counter is a permanent milestone: it only ever goes up.
const ACTIVE_DAY_MIN_MINUTES = 30;
const ACTIVE_MONTH_MIN_DAYS  = 20;
const TENURE_BADGES = [
  { id: "badge1", label: "Badge 1", labelAr: "الشارة 1", min: 1, max: 2,  color: "#CD7F32" },
  { id: "badge2", label: "Badge 2", labelAr: "الشارة 2", min: 3, max: 4,  color: "#9CA3AF" },
  { id: "badge3", label: "Badge 3", labelAr: "الشارة 3", min: 5, max: 6,  color: "#F1C40F" },
  { id: "badge4", label: "Badge 4", labelAr: "الشارة 4", min: 7, max: 8,  color: "#5DADE2" },
  { id: "badge5", label: "Badge 5", labelAr: "الشارة 5", min: 9, max: 12, color: "#9B59B6" },
];
// Returns the tier's label in the current UI language (falls back to French).
function tierLabel(tier) {
  if (!tier) return "";
  return getAppLang() === "ar" ? (tier.labelAr || tier.label) : tier.label;
}
function tenureBadgeForCount(activeMonthsCount) {
  if (!activeMonthsCount || activeMonthsCount < 1) return null;
  const last = TENURE_BADGES[TENURE_BADGES.length - 1];
  if (activeMonthsCount >= last.min) return last; // caps at Badge 5 past 12 months
  return TENURE_BADGES.find(b => activeMonthsCount >= b.min && activeMonthsCount <= b.max) || null;
}
function dateKeyOf(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}
// Credits `minutesToAdd` engaged minutes to today, then recomputes which
// calendar months have crossed the active-month threshold. Qualifying months
// are appended and kept forever (never removed), so the lifetime count is
// always non-decreasing and the tenure badge can never drop.
function recordActiveMinutes(s, minutesToAdd) {
  const todayKey = dateKeyOf(new Date());
  const dailyMinutes = { ...(s.dailyMinutes || {}) };
  dailyMinutes[todayKey] = (dailyMinutes[todayKey] || 0) + minutesToAdd;

  const activeDaysByMonth = {};
  for (const [dKey, mins] of Object.entries(dailyMinutes)) {
    if (mins < ACTIVE_DAY_MIN_MINUTES) continue;
    const mKey = dKey.slice(0, 7);
    activeDaysByMonth[mKey] = (activeDaysByMonth[mKey] || 0) + 1;
  }
  const tenureActiveMonths = [...(s.tenureActiveMonths || [])];
  for (const [mKey, count] of Object.entries(activeDaysByMonth)) {
    if (count >= ACTIVE_MONTH_MIN_DAYS && !tenureActiveMonths.includes(mKey)) {
      tenureActiveMonths.push(mKey);
    }
  }
  return { dailyMinutes, tenureActiveMonths };
}


