//  APP LANGUAGE (UI only — subject content is NOT affected) 
const APP_LANG_KEY = "school-maroc-lang";
let APP_LANG = null; // module-level so any component can read it via t()
function getAppLang() {
  try {
    if (!APP_LANG) APP_LANG = window.localStorage.getItem(APP_LANG_KEY) || null;
  } catch {}
  return APP_LANG;
}
function setAppLangStored(lang) {
  APP_LANG = lang;
  try { window.localStorage.setItem(APP_LANG_KEY, lang); } catch {}
  applyUIDirection(lang);
}
// Mirror the whole app UI when the interface language is Arabic.
// Lesson / quiz / chat content is NOT affected: those pages set their own
// explicit direction (content-based or subject-based) which overrides this.
function isUIRTL() { return getAppLang() === "ar"; }
function applyUIDirection(lang) {
  const dir = lang === "ar" ? "rtl" : "ltr";
  try {
    document.documentElement.setAttribute("dir", dir);
    document.documentElement.setAttribute("lang", lang === "ar" ? "ar" : "fr");
    if (document.body) document.body.setAttribute("dir", dir);
  } catch {}
}

