// t(): returns the Arabic UI string when the app language is Arabic,
// otherwise the French text as written. Subjects/lesson content never pass here.
function t(fr) {
  if (getAppLang() === "ar") return (UI_TR.ar[fr] !== undefined ? UI_TR.ar[fr] : fr);
  return fr;
}


