//  REMEMBER LAST NIVEAU / GRADE / FILIERE 
// Persists the user's last selection so reopening the app lands on the
// subjects page (page 3) instead of the niveau picker. We store ids only and
// resolve them back to the canonical CURRICULUM objects on restore.
const SAVED_NAV_KEY = "school-maroc-nav";
function loadSavedNav() {
  try {
    const raw = window.localStorage.getItem(SAVED_NAV_KEY);
    if (!raw) return {};
    const saved = JSON.parse(raw);
    const niveau = saved.niveauKey && CURRICULUM[saved.niveauKey] ? saved.niveauKey : null;
    if (!niveau) return {};
    const grade = saved.gradeId
      ? (CURRICULUM[niveau].grades.find(g => g.id === saved.gradeId) || null)
      : null;
    let filiere = null;
    if (grade && saved.filiereId) {
      const arr = grade.id === "tc" ? TC_FILIERES
        : grade.id === "1bac" ? BAC1_FILIERES
        : grade.id === "2bac" ? BAC2_FILIERES : null;
      if (arr) filiere = arr.find(f => f.id === saved.filiereId) || null;
    }
    return { niveau, grade, filiere };
  } catch {
    return {};
  }
}
function savedNavLandsOnSubjects(nav) {
  return !!(nav.grade && (["tc", "1bac", "2bac"].includes(nav.grade.id) ? nav.filiere : true));
}

