//  Helper: resolve content for current grade + subject + lesson title 
function getContent(gradeId, subjectId, lessonTitle) {
  return CONTENT?.[gradeId]?.[subjectId]?.[lessonTitle] ?? null;
}

//  CLOUD LESSONS (Firestore "lessons" collection, edited from the admin tool) 
// Doc id = `${gradeId}__${subjectId}__${lessonTitle}`. Lessons are read at
// runtime, cached to localStorage for offline use, and fall back to the baked
// CONTENT object above if the cloud is unreachable. No rebuild needed to add a
// lesson — write it from admin.html and it appears in the app.
const LESSON_CACHE_PREFIX = "lesson-cache:";
function lessonDocId(gradeId, subjectId, lessonTitle) {
  return `${gradeId}__${subjectId}__${lessonTitle}`;
}
function cachedLesson(gradeId, subjectId, lessonTitle) {
  try {
    const raw = localStorage.getItem(LESSON_CACHE_PREFIX + lessonDocId(gradeId, subjectId, lessonTitle));
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}
// Best available copy WITHOUT a network call: baked CONTENT, else cached cloud copy.
function localLesson(gradeId, subjectId, lessonTitle) {
  return getContent(gradeId, subjectId, lessonTitle) || cachedLesson(gradeId, subjectId, lessonTitle);
}
async function fetchCloudLesson(gradeId, subjectId, lessonTitle) {
  const { db, fsMod } = await loadFirestore();
  const ref = fsMod.doc(db, "lessons", lessonDocId(gradeId, subjectId, lessonTitle));
  const snap = await fsMod.getDoc(ref);
  if (!snap.exists()) return null;
  const data = snap.data();
  try { localStorage.setItem(LESSON_CACHE_PREFIX + lessonDocId(gradeId, subjectId, lessonTitle), JSON.stringify(data)); } catch {}
  return data;
}

// List the lesson titles published for a grade+subject (the "indexes" doc the
// editor maintains). Used to build the pool for the daily quiz.
async function fetchCloudTitles(gradeId, subjectId) {
  const { db, fsMod } = await loadFirestore();
  const ref = fsMod.doc(db, "indexes", `${gradeId}__${subjectId}`);
  const snap = await fsMod.getDoc(ref);
  return snap.exists() ? (snap.data().titles || []) : [];
}

// The quiz engine expects {type, question, options, answer, explanation}; the
// editor saves {q, opts, ans, exp}. Normalize so both formats render correctly.
function normalizeQuiz(arr) {
  return (arr || []).map(e => ({
    type: e.type || "qcm",
    question: e.question ?? e.q ?? "",
    options: e.options || e.opts || [],
    answer: e.answer ?? e.ans ?? "",
    explanation: e.explanation ?? e.exp ?? "",
    size: e.size,
  }));
}

// Auto text direction from the lesson's own content: collect all the text in a
// lesson object, count Arabic-script vs Latin letters, and decide. This lets an
// Arabic lesson render right-to-left even under a "LTR" subject like Maths.
const ARABIC_RE = /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/g;
const LATIN_RE = /[A-Za-zÀ-ÿ]/g;
function _collectText(node, acc, depth) {
  if (node == null || depth > 6) return acc;
  if (typeof node === "string") {
    // skip images / links / hex colors — not real reading text
    if (!/^data:|^https?:\/\//i.test(node) && !/^#?[0-9a-fA-F]{3,8}$/.test(node)) acc.push(node);
    return acc;
  }
  if (Array.isArray(node)) { for (const v of node) _collectText(v, acc, depth + 1); return acc; }
  if (typeof node === "object") { for (const k in node) _collectText(node[k], acc, depth + 1); return acc; }
  return acc;
}
// Render stored rich-text. Old lessons may have plain strings (render fine as
// HTML) or arrays for points/à retenir/astuce (joined with line breaks).
const asHtml = (v) => Array.isArray(v) ? v.map(x => (x == null ? "" : String(x))).join("<br>") : (v == null ? "" : String(v));
function lessonRTL(entry, fallback) {
  if (!entry) return fallback;
  // Strip HTML markup before counting: inserted icons carry inline <svg> path
  // data and shapes carry CSS — both Latin-heavy — which would otherwise
  // outweigh the Arabic text and wrongly flip the lesson to LTR.
  const text = _collectText(entry, [], 0).join(" ").replace(/<[^>]*>/g, " ");
  const ar = (text.match(ARABIC_RE) || []).length;
  const la = (text.match(LATIN_RE) || []).length;
  if (ar === 0 && la === 0) return fallback;
  return ar > la;
}

//  CLOUD LESSON INDEX (extra lessons created from the admin tool) 
// Doc id `lesson-index/${gradeId}__${subjectId}` = { extras: [{ unit:<index>, title }] }.
// The app appends these to the matching unit's built-in lesson list (deduped).
const INDEX_CACHE_PREFIX = "lesson-index-cache:";
function cachedIndex(gradeId, subjectId) {
  try {
    const raw = localStorage.getItem(INDEX_CACHE_PREFIX + gradeId + "__" + subjectId);
    return raw ? JSON.parse(raw) : [];
  } catch { return []; }
}
async function fetchLessonIndex(gradeId, subjectId) {
  const { db, fsMod } = await loadFirestore();
  const ref = fsMod.doc(db, "lesson-index", gradeId + "__" + subjectId);
  const snap = await fsMod.getDoc(ref);
  const extras = snap.exists() ? (snap.data().extras || []) : [];
  try { localStorage.setItem(INDEX_CACHE_PREFIX + gradeId + "__" + subjectId, JSON.stringify(extras)); } catch {}
  return extras;
}

